sys_script_include.script:
var CheckExistingDate = Class.create();
CheckExistingDate.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    isDuplicateDate: function() {
        var selectedDate = this.getParameter('sysparm_date');
        var tableName = this.getParameter('sysparm_table');
		var courseName = this.getParameter('sysparm_course');

        var gr = new GlideRecord(tableName);
        gr.addQuery('training_date', selectedDate);
		gr.addQuery('course', courseName); 
        gr.query();

        return gr.hasNext();
    },
    type: 'CheckExistingDate'
});
